-- Primary-abstract extraction, 30 September 2026. Single reviewer; no full-text promotion.
CREATE TABLE IF NOT EXISTS ilb_ehr_candidate_extraction (
 practice_code VARCHAR(64) NOT NULL, pmid VARCHAR(20) NOT NULL,
 material_reviewed ENUM('ABSTRACT','NO_ABSTRACT') NOT NULL,
 interpretation_text TEXT NOT NULL, remaining_work TEXT NOT NULL, reviewed_on DATE NOT NULL,
 reviewer_text VARCHAR(128) NOT NULL, PRIMARY KEY(practice_code,pmid),
 CONSTRAINT fk_ehr_extraction_candidate FOREIGN KEY(practice_code,pmid) REFERENCES ilb_ehr_candidate_screen(practice_code,pmid)
 ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
START TRANSACTION;
INSERT INTO ilb_ehr_candidate_extraction (practice_code,pmid,material_reviewed,interpretation_text,remaining_work,reviewed_on,reviewer_text) VALUES ('PRANIC_HEALING','38939830','ABSTRACT','88 teachers randomized to facing versus opposite hands, maximum 120 seconds. Sensations reported by 44 versus 13; this measures subjective perception, not objective energy detection or therapeutic benefit.','Verify original full text and lineage; independently assess bias, registry/endpoint match, funding, safety and publisher updates. Do not count overlapping reports independently.','2026-09-30','ILMB single-reviewer abstract extraction') ON DUPLICATE KEY UPDATE material_reviewed=VALUES(material_reviewed),interpretation_text=VALUES(interpretation_text),remaining_work=VALUES(remaining_work),reviewed_on=VALUES(reviewed_on),reviewer_text=VALUES(reviewer_text);
UPDATE ilb_ehr_candidate_screen SET screening_status='ABSTRACT_EXTRACTED_FULL_REVIEW_PENDING',screening_reason='88 teachers randomized to facing versus opposite hands, maximum 120 seconds. Sensations reported by 44 versus 13; this measures subjective perception, not objective energy detection or therapeutic benefit.' WHERE practice_code='PRANIC_HEALING' AND pmid='38939830';
UPDATE ilb_ehr_screen_assessment SET screening_level='ABSTRACT',assessed_on='2026-09-30' WHERE practice_code='PRANIC_HEALING' AND pmid='38939830';
