INSERT INTO ilb_ehr_candidate_extraction (practice_code,pmid,material_reviewed,interpretation_text,remaining_work,reviewed_on,reviewer_text) VALUES ('REIKI','41051913','ABSTRACT','60 ventilated patients randomized to 30-minute Reiki or sham. Pain/anxiety comparisons favored Reiki; systolic pressure p=.052. Effect magnitudes, allocation concealment and registry match NCT06526949 require full-text verification.','Verify original full text and lineage; independently assess bias, registry/endpoint match, funding, safety and publisher updates. Do not count overlapping reports independently.','2026-09-30','ILMB single-reviewer abstract extraction') ON DUPLICATE KEY UPDATE material_reviewed=VALUES(material_reviewed),interpretation_text=VALUES(interpretation_text),remaining_work=VALUES(remaining_work),reviewed_on=VALUES(reviewed_on),reviewer_text=VALUES(reviewer_text);
