UPDATE ilb_ehr_candidate_screen SET screening_status='ABSTRACT_EXTRACTED_FULL_REVIEW_PENDING',screening_reason='40 students randomized to Reiki or control during guided relaxation, six 30-minute sessions. Mood benefit reported in high-anxiety/depression subgroup at five-week follow-up; small subgroup and multiple outcomes limit interpretation.' WHERE practice_code='REIKI' AND pmid='21584234';
UPDATE ilb_ehr_screen_assessment SET screening_level='ABSTRACT',assessed_on='2026-09-30' WHERE practice_code='REIKI' AND pmid='21584234';
INSERT INTO ilb_ehr_candidate_extraction (practice_code,pmid,material_reviewed,interpretation_text,remaining_work,reviewed_on,reviewer_text) VALUES ('REIKI','36272846','ABSTRACT','159 endoscopy patients, three-arm randomized Reiki/sham/control trial; one 20-25-minute session. Stress/anxiety/comfort comparisons reported p<.001; effect sizes and full masking/attrition details absent from abstract.','Verify original full text and lineage; independently assess bias, registry/endpoint match, funding, safety and publisher updates. Do not count overlapping reports independently.','2026-09-30','ILMB single-reviewer abstract extraction') ON DUPLICATE KEY UPDATE material_reviewed=VALUES(material_reviewed),interpretation_text=VALUES(interpretation_text),remaining_work=VALUES(remaining_work),reviewed_on=VALUES(reviewed_on),reviewer_text=VALUES(reviewer_text);
UPDATE ilb_ehr_candidate_screen SET screening_status='ABSTRACT_EXTRACTED_FULL_REVIEW_PENDING',screening_reason='159 endoscopy patients, three-arm randomized Reiki/sham/control trial; one 20-25-minute session. Stress/anxiety/comfort comparisons reported p<.001; effect sizes and full masking/attrition details absent from abstract.' WHERE practice_code='REIKI' AND pmid='36272846';
UPDATE ilb_ehr_screen_assessment SET screening_level='ABSTRACT',assessed_on='2026-09-30' WHERE practice_code='REIKI' AND pmid='36272846';
INSERT INTO ilb_ehr_candidate_extraction (practice_code,pmid,material_reviewed,interpretation_text,remaining_work,reviewed_on,reviewer_text) VALUES ('REIKI','36481177','ABSTRACT','93 abdominal surgery patients randomized equally to Reiki, sham or control. Favorable fear/anxiety/pain/oxygen findings reported without detailed contrasts or dose; abstract cannot establish blanket safety or routine-care efficacy.','Verify original full text and lineage; independently assess bias, registry/endpoint match, funding, safety and publisher updates. Do not count overlapping reports independently.','2026-09-30','ILMB single-reviewer abstract extraction') ON DUPLICATE KEY UPDATE material_reviewed=VALUES(material_reviewed),interpretation_text=VALUES(interpretation_text),remaining_work=VALUES(remaining_work),reviewed_on=VALUES(reviewed_on),reviewer_text=VALUES(reviewer_text);
UPDATE ilb_ehr_candidate_screen SET screening_status='ABSTRACT_EXTRACTED_FULL_REVIEW_PENDING',screening_reason='93 abdominal surgery patients randomized equally to Reiki, sham or control. Favorable fear/anxiety/pain/oxygen findings reported without detailed contrasts or dose; abstract cannot establish blanket safety or routine-care efficacy.' WHERE practice_code='REIKI' AND pmid='36481177';
UPDATE ilb_ehr_screen_assessment SET screening_level='ABSTRACT',assessed_on='2026-09-30' WHERE practice_code='REIKI' AND pmid='36481177';
INSERT INTO ilb_ehr_candidate_extraction (practice_code,pmid,material_reviewed,interpretation_text,remaining_work,reviewed_on,reviewer_text) VALUES ('REIKI','33639516','ABSTRACT','48 block-randomized to Reiki, sham or no treatment. No significant between-group differences in heart rate, pressure, temperature or stress. Reiki-sham heart-rate p=.053 remains nonsignificant.','Verify original full text and lineage; independently assess bias, registry/endpoint match, funding, safety and publisher updates. Do not count overlapping reports independently.','2026-09-30','ILMB single-reviewer abstract extraction') ON DUPLICATE KEY UPDATE material_reviewed=VALUES(material_reviewed),interpretation_text=VALUES(interpretation_text),remaining_work=VALUES(remaining_work),reviewed_on=VALUES(reviewed_on),reviewer_text=VALUES(reviewer_text);
