UPDATE ilb_ehr_screen_assessment SET screening_level='ABSTRACT',assessed_on='2026-09-30' WHERE practice_code='REIKI' AND pmid='33639516';
INSERT INTO ilb_ehr_candidate_extraction (practice_code,pmid,material_reviewed,interpretation_text,remaining_work,reviewed_on,reviewer_text) VALUES ('REIKI','33053005','ABSTRACT','122 randomized, 101 studied; massage plus rest, massage plus Reiki, or no intervention. Both active packages improved outcomes versus control. Massage confounds attribution; Reiki-specific incremental effect needs full contrast extraction.','Verify original full text and lineage; independently assess bias, registry/endpoint match, funding, safety and publisher updates. Do not count overlapping reports independently.','2026-09-30','ILMB single-reviewer abstract extraction') ON DUPLICATE KEY UPDATE material_reviewed=VALUES(material_reviewed),interpretation_text=VALUES(interpretation_text),remaining_work=VALUES(remaining_work),reviewed_on=VALUES(reviewed_on),reviewer_text=VALUES(reviewer_text);
UPDATE ilb_ehr_candidate_screen SET screening_status='ABSTRACT_EXTRACTED_FULL_REVIEW_PENDING',screening_reason='122 randomized, 101 studied; massage plus rest, massage plus Reiki, or no intervention. Both active packages improved outcomes versus control. Massage confounds attribution; Reiki-specific incremental effect needs full contrast extraction.' WHERE practice_code='REIKI' AND pmid='33053005';
UPDATE ilb_ehr_screen_assessment SET screening_level='ABSTRACT',assessed_on='2026-09-30' WHERE practice_code='REIKI' AND pmid='33053005';
