UPDATE ilb_ehr_screen_assessment SET screening_level='ABSTRACT',assessed_on='2026-09-30' WHERE practice_code='EXTERNAL_QIGONG' AND pmid='15102336';
INSERT INTO ilb_ehr_candidate_extraction (practice_code,pmid,material_reviewed,interpretation_text,remaining_work,reviewed_on,reviewer_text) VALUES ('SAHAJA_YOGA','9062044','ABSTRACT','32 epilepsy patients randomized 10/10/12 to six-month Sahaja, mimicking exercise or control. Large within-meditation seizure reductions reported; controlled contrasts/medication stability/full bias assessment needed. Likely related cohort with PMIDs7649596/10832506, not three independent trials.','Verify original full text and lineage; independently assess bias, registry/endpoint match, funding, safety and publisher updates. Do not count overlapping reports independently.','2026-09-30','ILMB single-reviewer abstract extraction') ON DUPLICATE KEY UPDATE material_reviewed=VALUES(material_reviewed),interpretation_text=VALUES(interpretation_text),remaining_work=VALUES(remaining_work),reviewed_on=VALUES(reviewed_on),reviewer_text=VALUES(reviewer_text);
UPDATE ilb_ehr_candidate_screen SET screening_status='ABSTRACT_EXTRACTED_FULL_REVIEW_PENDING',screening_reason='32 epilepsy patients randomized 10/10/12 to six-month Sahaja, mimicking exercise or control. Large within-meditation seizure reductions reported; controlled contrasts/medication stability/full bias assessment needed. Likely related cohort with PMIDs7649596/10832506, not three independent trials.' WHERE practice_code='SAHAJA_YOGA' AND pmid='9062044';
UPDATE ilb_ehr_screen_assessment SET screening_level='ABSTRACT',assessed_on='2026-09-30' WHERE practice_code='SAHAJA_YOGA' AND pmid='9062044';
INSERT INTO ilb_ehr_candidate_extraction (practice_code,pmid,material_reviewed,interpretation_text,remaining_work,reviewed_on,reviewer_text) VALUES ('SAHAJA_YOGA','7649596','ABSTRACT','32 epilepsy patients in three six-month Sahaja/mimic/control groups. Stress-marker within-group changes reported. Likely overlaps seizure/evoked-potential reports PMIDs9062044/10832506; verify cohort and avoid independent replication counting.','Verify original full text and lineage; independently assess bias, registry/endpoint match, funding, safety and publisher updates. Do not count overlapping reports independently.','2026-09-30','ILMB single-reviewer abstract extraction') ON DUPLICATE KEY UPDATE material_reviewed=VALUES(material_reviewed),interpretation_text=VALUES(interpretation_text),remaining_work=VALUES(remaining_work),reviewed_on=VALUES(reviewed_on),reviewer_text=VALUES(reviewer_text);
