UPDATE ilb_ehr_screen_assessment SET screening_level='ABSTRACT',assessed_on='2026-09-30' WHERE practice_code='HEALING_DOWSING' AND pmid='754193';
INSERT INTO ilb_ehr_candidate_extraction (practice_code,pmid,material_reviewed,interpretation_text,remaining_work,reviewed_on,reviewer_text) VALUES ('HEALING_DOWSING','22365422','ABSTRACT','Reanalysis of dowsing field experiments proposing radio-frequency interference. Correlations not present at all sites; hypothesis is not a controlled therapeutic efficacy test or validated diagnostic ability.','Verify original full text and lineage; independently assess bias, registry/endpoint match, funding, safety and publisher updates. Do not count overlapping reports independently.','2026-09-30','ILMB single-reviewer abstract extraction') ON DUPLICATE KEY UPDATE material_reviewed=VALUES(material_reviewed),interpretation_text=VALUES(interpretation_text),remaining_work=VALUES(remaining_work),reviewed_on=VALUES(reviewed_on),reviewer_text=VALUES(reviewer_text);
