UPDATE ilb_ehr_screen_assessment SET screening_level='ABSTRACT',assessed_on='2026-09-30' WHERE practice_code='HEALING_DOWSING' AND pmid='22365422';
UPDATE ilb_ehr_research_gate g SET summary_text=CONCAT('Research remains open. Earlier cohort: ',(SELECT COUNT(*) FROM ilb_ehr_candidate_screen c WHERE c.practice_code=g.practice_code AND c.screening_status='ABSTRACT_EXTRACTED_FULL_REVIEW_PENDING'),' abstract-extracted mappings need full review; ',(SELECT COUNT(*) FROM ilb_ehr_candidate_screen c WHERE c.practice_code=g.practice_code AND c.screening_status='SOURCE_GAP_NO_ABSTRACT'),' records lack an abstract; ',(SELECT COUNT(*) FROM ilb_ehr_candidate_screen c WHERE c.practice_code=g.practice_code AND c.screening_status='IDENTITY_UNCONFIRMED'),' identities unresolved. Expanded PubMed metadata retrieved; eligibility screening remains open.'),reviewed_on='2026-09-30',research_complete=0;
COMMIT;
